mapper.select:
SELECT /* homes.batch.mapper.BatchMapper.getHBT001Count */
       COUNT(1) AS BATCO
FROM   TB_HBD_TEMP_BSOUTLINE
WHERE  BATCH_DE = #{batchde}
AND    BATCH_AT = #{batchAt}

		SELECT /* homes.batch.mapper.BatchMapper.getHomesHtbdno */

		       CASE WHEN ( SELECT COUNT(1) FROM TB_HBD_BASE_SUMMRY WHERE TOTAL_REGSTR_PK = #{totalRegstrPk} ) = 0 
		            THEN /* TOTAL_REGSTR_PK가 있고 COUNT가 0인경우 신규채번 */ 
                         CONCAT('HTB', LPAD(#{buldgb}, 2, '0'), #{arcd}, #{legcd}
                                     , LPAD(NVL(MAX(SUBSTR(A.HTBDNO, 15)), 0) + 1, 7, '0'))
                    ELSE /* 기존사용하던 HTBDNO를 리턴 */
                         ( SELECT HTBDNO FROM TB_HBD_BASE_SUMMRY WHERE TOTAL_REGSTR_PK = #{totalRegstrPk} LIMIT 1 )
               END AS HTBDNO


		       /* 무조건 신규채번 */ 
               CONCAT('HTB', LPAD(#{buldgb}, 2, '0'), #{arcd}, #{legcd}
                           , LPAD(NVL(MAX(SUBSTR(A.HTBDNO, 15)), 0) + 1, 7, '0')) AS HTBDNO

		FROM   TB_HBD_BASE_SUMMRY A
		WHERE  BULDGB = #{buldgb}
		AND    ARCD = #{arcd}
		AND    LEGCD = #{legcd}

		SELECT /* homes.batch.mapper.BatchMapper.getHomesBuldno */
               CONCAT('HBD', LPAD(#{buldgb}, 2, '0'), #{arcd}, #{legcd}
                           , LPAD(NVL(MAX(SUBSTR(A.HBDNO, 15)), 0) + 1, 7, '0')) AS HBDNO
		FROM   TB_HBD_BASE_SUMMRY A
		WHERE  BULDGB = #{buldgb}
		AND    ARCD = #{arcd}
		AND    LEGCD = #{legcd}

mapper.insert:
INSERT /* homes.batch.mapper.BatchMapper.insertBaseSummry 기본개요 등록 */ INTO TB_HBD_BASE_SUMMRY ( HTBDNO, HBDNO, TOTAL_REGSTR_PK, BULD_REGSTR_PK , BULDGB, CPLX_AT, ARCD, LEGCD, BUNJIB, BUNJIJ , RDCODE, RDLEGCD, UNDER_AT, RD_MAIN_BUN, RD_SUB_BUN , BATCH_AT, BATCH_DE, USE_YN, CREAT_USER_NO, UPDT_USER_NO ) SELECT #{htbdno} AS HTBDNO , #{hbdno} AS HBDNO , A.TOTAL_REGSTR_PK AS TOTAL_REGSTR_PK , A.BULD_REGSTR_PK AS BULD_REGSTR_PK , A.BULDGB AS BULDGB , A.BULDGB AS CPLX_AT , A.ARCD AS ARCD , A.LEGCD AS LEGCD , A.BUNJIB AS BUNJIB , A.BUNJIJ AS BUNJIJ , A.RDCODE AS RDCODE , A.RDLEGCD AS RDLEGCD , A.UNDER_AT AS UNDER_AT , A.RD_MAIN_BUN AS RD_MAIN_BUN , A.RD_SUB_BUN AS RD_SUB_BUN , '1' AS BATCH_AT , #{batchde} AS BATCH_DE , 'Y' AS USE_YN , #{mngrno} AS CREAT_USER_NO , #{mngrno} AS UPDT_USER_NO FROM TB_HBD_TEMP_BSOUTLINE A WHERE A.BULD_REGSTR_PK = #{buldRegstrPk}
AND A.TOTAL_REGSTR_PK = #{totalRegstrPk}
AND A.BATCH_DE = #{batchde} AND A.BATCH_AT = #{batchAt}

	INSERT /* homes.batch.mapper.BatchMapper.insertBatchjob */ 
	INTO TB_CM_BATCHJOB (
		BT_UUID
		, BATCHTY
		, BT_STTUS_CD
        , BT_EXCO 
        , BT_FILENM 
		, BT_ERROR_MSG
		, BT_ST_DT
		, CREAT_USER_NO
		, CREAT_DT
		, UPDT_USER_NO
		, UPDT_DT
	) VALUES(
		#{uuid}
		, #{batchty}
		, #{sttuscd}
		, #{exco}
		, #{filenm}
		, #{message}
		, NOW()
		, #{mngrno}
		, NOW()
		, #{mngrno}
		, NOW()
	)

	INSERT /* homes.batch.mapper.BatchMapper.insertBatchLog */ 
	INTO TB_CM_BATCHJOB (
		BT_UUID
		, BATCHTY
		, BT_STTUS_CD
        , BT_EXCO 
        , BT_FILENM 
		, BT_ERROR_MSG
		, BT_ST_DT
		, CREAT_USER_NO
		, CREAT_DT
		, UPDT_USER_NO
		, UPDT_DT
	) VALUES(
		#{uuid}
		, #{batchty}
		, #{sttuscd}
		, #{exco}
		, #{filenm}
		, #{message}
		, NOW()
		, #{mngrno}
		, NOW()
		, #{mngrno}
		, NOW()
	)

mapper.update:
UPDATE /* homes.batch.mapper.BatchMapper.updateLegcdTotalLedger */	
       TB_BD_TITLE_LEDGR
SET    LEGCD = #{legcode}
WHERE  ARCD = #{arcode}
AND    LEGCD IS NULL
AND    PLOT_LOC LIKE CONCAT(#{arname}, '%')

UPDATE /* homes.batch.mapper.BatchMapper.updateBaseOutLine */
       TB_HBD_TEMP_BSOUTLINE
SET    BATCH_AT = #{afBatchAt}
       , UPDT_USER_NO = #{mngrno}
       , UPDT_DT = NOW()
WHERE  BATCH_DE = #{batchde}
AND    BATCH_AT = #{bfBatchAt}
AND    BULD_REGSTR_PK = #{buldRegstrPk}

AND    TOTAL_REGSTR_PK = #{totalRegstrPk}

UPDATE /* homes.batch.mapper.BatchMapper.updateBatchLog */ 
       TB_CM_BATCHJOB
SET    BT_STTUS_CD = #{sttuscd}
       , BT_ED_DT = NOW()
       , BT_EXCO = #{exco}
       , BT_FILENM = #{filenm}
       , BT_ERROR_MSG = #{message}
       , UPDT_USER_NO = #{mngrno} 
       , UPDT_DT = NOW()
WHERE  BT_UUID = #{uuid}

UPDATE /* homes.batch.mapper.BatchMapper.updateBatchjob */ 
       TB_CM_BATCHJOB
SET    BT_STTUS_CD = #{sttuscd}
       , BT_ED_DT = NOW()
       , BT_EXCO = #{exco}
       , BT_FILENM = #{filenm}
       , BT_ERROR_MSG = #{message}
       , UPDT_USER_NO = #{mngrno} 
       , UPDT_DT = NOW()
WHERE  BT_UUID = #{uuid}

UPDATE /* homes.batch.mapper.BatchMapper.updateLedgrHtbdno */ 
       TB_HBD_LEDGR
SET    HTBDNO = #{htbdno}
       , TOTAL_REGSTR_PK = #{buldRegstrPk}
       , UPDT_DT = NOW() 
WHERE  ARCD = #{arcd}
AND    LEGCD = #{legcd}
AND    BUNJIB = #{bunjib}
AND    RDCODE = #{rdcode}
AND    RD_MAIN_BUN = #{rdMainBun}
